// ============================================================================
// CRIMSON NIGHT & NEO — SUPPLEMENTARY GITHUB IMAGE ASSET BUNDLE
// Upload this file (crimson-night-images.js) alongside crimson-night.html
// ============================================================================
window.CRIMSON_NIGHT_IMAGES = {
  'assets/neo-official-logo.png': 'data:image/png;base64,',
  'assets/neo-logo-transparent.png': 'data:image/png;base64,',
  'assets/crimson-night-official-logo.png': 'data:image/png;base64,',
  'assets/crimson-night-logo-transparent.png': 'data:image/png;base64,',
  'assets/crimson-night-character-concept.png': 'data:image/png;base64,',
  'assets/crimson-night-merchandise-collector.webp': 'data:image/webp;base64,',
  'assets/malakor-weeping-archon.jpg': 'data:image/jpeg;base64,',
  'assets/lady-vespera-npc.jpg': 'data:image/jpeg;base64,',
  'assets/ossuary-amalgam.jpg': 'data:image/jpeg;base64,',
  'assets/trailer-kaelen-bloodmoon.jpg': 'data:image/jpeg;base64,',
  'assets/trailer-kaelen-closeup.jpg': 'data:image/jpeg;base64,',
  'assets/trailer-scene-1-eclipse.jpg': 'data:image/jpeg;base64,',
  'assets/trailer-scene-2-kaelen-combat.jpg': 'data:image/jpeg;base64,',
  'assets/trailer-scene-4-halo-crossover.jpg': 'data:image/jpeg;base64,',
  'assets/halo-crimson-collab.jpg': 'data:image/jpeg;base64,',
  'assets/crimson-night-art.jpg': 'data:image/jpeg;base64,',
};

(function applyCrimsonNightImages() {
  const bank = window.CRIMSON_NIGHT_IMAGES;
  if (!bank) return;

  function resolveAssetUri(src) {
    if (!src) return null;
    if (bank[src]) return bank[src];
    const idx = src.indexOf('assets/');
    if (idx !== -1) {
      const rel = src.substring(idx);
      if (bank[rel]) return bank[rel];
    }
    return null;
  }

  function hydrateAllImages() {
    document.querySelectorAll('img').forEach(img => {
      const rawSrc = img.getAttribute('src') || '';
      const dataUri = resolveAssetUri(rawSrc);
      if (dataUri && img.src !== dataUri) {
        img.src = dataUri;
      }
      img.addEventListener('error', function() {
        const fallback = resolveAssetUri(this.getAttribute('src') || '');
        if (fallback && this.src !== fallback) {
          this.src = fallback;
        }
      });
    });

    if (typeof trailerImages !== 'undefined' && typeof trailerAssetSources !== 'undefined') {
      Object.keys(trailerAssetSources).forEach(key => {
        const path = trailerAssetSources[key];
        const dataUri = resolveAssetUri(path);
        if (dataUri && trailerImages[key]) {
          trailerImages[key].src = dataUri;
        }
      });
    }

    if (typeof ostTracks !== 'undefined' && Array.isArray(ostTracks)) {
      ostTracks.forEach(t => {
        const dataUri = resolveAssetUri(t.cover);
        if (dataUri) t.cover = dataUri;
      });
    }
  }

  function wrapLightbox() {
    if (typeof window.openLightbox === 'function' && !window.openLightbox._wrappedByBundle) {
      const orig = window.openLightbox;
      const wrapped = function(src, title, desc) {
        return orig(resolveAssetUri(src) || src, title, desc);
      };
      wrapped._wrappedByBundle = true;
      window.openLightbox = wrapped;
    }
  }

  hydrateAllImages();
  wrapLightbox();

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      hydrateAllImages();
      wrapLightbox();
    });
  }
  window.addEventListener('load', () => {
    hydrateAllImages();
    wrapLightbox();
  });
})();
